      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">RUN THE GOOGLE TEST</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">15 minutes. Three candidates. Real data.</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"235\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">1.</text>\n                    <text x=\"230\" y=\"230\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Use private/incognito window</text>\n                    <text x=\"230\" y=\"260\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Personalized results bias you</text>\n                    <rect x=\"100\" y=\"300\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"355\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">2.</text>\n                    <text x=\"230\" y=\"350\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Quoted exact phrase</text>\n                    <text x=\"230\" y=\"380\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Count results, note top 3 names</text>\n                    <rect x=\"100\" y=\"420\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"475\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">3.</text>\n                    <text x=\"230\" y=\"470\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Unquoted version</text>\n                    <text x=\"230\" y=\"500\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Who dominates page 1?</text>\n                    <rect x=\"100\" y=\"540\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"595\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">4.</text>\n                    <text x=\"230\" y=\"590\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">2-3 synonym variations</text>\n                    <text x=\"230\" y=\"620\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Same names? It's saturated.</text>\n                    <rect x=\"100\" y=\"660\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"715\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">5.</text>\n                    <text x=\"230\" y=\"710\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Score 1-10 defensibility</text>\n                    <text x=\"230\" y=\"740\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">10 = open whitespace</text>\n                    <rect x=\"100\" y=\"780\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"835\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Bonus: same searches on YouTube and Substack.</text>\n                    <text x=\"550\" y=\"870\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Different platforms reveal different whitespace.</text>\n                </svg>",
      "caption": "Let the data pick your Tilt"
