      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">What COPE actually means</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"220\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"245\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"32\">COPE</text>\n                    <text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">Create Once,</text>\n                    <text x=\"550\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">Publish Everywhere</text>\n                    <rect x=\"100\" y=\"430\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"495\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">ONE PILLAR</text>\n                    <text x=\"550\" y=\"545\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Long-form audio, video, or article</text>\n                    <text x=\"550\" y=\"585\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Dense enough to harvest many derivatives</text>\n                    <rect x=\"100\" y=\"660\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"26\">MANY DERIVATIVES</text>\n                    <text x=\"550\" y=\"775\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Blog. Clips. Quotes. Newsletter. Carousel. Deck.</text>\n                    <text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">One creation = a week of content</text>\n                </svg>",
      "caption": "Create once, distribute many"
