      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">YOUR FIRST MONETIZATION</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">90 days, five steps</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"235\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">1.</text>\n                    <text x=\"230\" y=\"230\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">Survey audience (5 questions)</text>\n                    <text x=\"230\" y=\"265\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Goal: 50-100 responses</text>\n                    <rect x=\"100\" y=\"320\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"375\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"26\">2.</text>\n                    <text x=\"230\" y=\"370\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">Pick high-margin pilot offer</text>\n                    <text x=\"230\" y=\"405\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">$500-$5,000 range. Not a $20 ebook.</text>\n                    <rect x=\"100\" y=\"460\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"515\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">3.</text>\n                    <text x=\"230\" y=\"510\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">Pre-sell to superfans</text>\n                    <text x=\"230\" y=\"545\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Less than 5 sold = kill the idea</text>\n                    <rect x=\"100\" y=\"600\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"655\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"26\">4.</text>\n                    <text x=\"230\" y=\"650\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">Deliver, document, refine</text>\n                    <text x=\"230\" y=\"685\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Collect testimonials and case studies</text>\n                    <rect x=\"100\" y=\"740\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"795\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"26\">5.</text>\n                    <text x=\"230\" y=\"790\" text-anchor=\"start\" fill=\"#fff\" font-size=\"22\">Public launch with proof</text>\n                    <text x=\"230\" y=\"825\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Convert 1-3% of full list</text>\n                </svg>",
      "caption": "Pilot → prove → scale"
