      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">DESIGN 3 OFFERS</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">30 minutes. Seven fields each.</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"230\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">1.</text>\n                    <text x=\"230\" y=\"230\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Title and description</text>\n                    <text x=\"230\" y=\"260\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">What it is in one line</text>\n                    <rect x=\"100\" y=\"300\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"350\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">2.</text>\n                    <text x=\"230\" y=\"350\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Problem solved</text>\n                    <text x=\"230\" y=\"380\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Specific pain it addresses</text>\n                    <rect x=\"100\" y=\"420\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"470\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">3.</text>\n                    <text x=\"230\" y=\"470\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Format</text>\n                    <text x=\"230\" y=\"500\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Cohort, service, course, event, 1:1</text>\n                    <rect x=\"100\" y=\"540\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"590\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">4.</text>\n                    <text x=\"230\" y=\"590\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Price point</text>\n                    <text x=\"230\" y=\"620\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">$500, $2K, $5K — and why</text>\n                    <rect x=\"100\" y=\"660\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(20,184,166,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"710\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">5.</text>\n                    <text x=\"230\" y=\"710\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Delivery effort per buyer</text>\n                    <text x=\"230\" y=\"740\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Sustainable at scale?</text>\n                    <rect x=\"100\" y=\"780\" width=\"900\" height=\"100\" rx=\"20\" fill=\"rgba(236,72,153,0.15)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"830\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">6-7.</text>\n                    <text x=\"260\" y=\"830\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Conversion rate + revenue projection</text>\n                    <text x=\"260\" y=\"860\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Buyers × price = first-launch revenue</text>\n                </svg>",
      "caption": "Spec it, rank it, pick one"
