      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The 6:1 monetization density ratio</text>\n                    <rect x=\"100\" y=\"180\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"245\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">TOO HOT (1:1 or 3:1)</text>\n                    <text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Audience feels like targets</text>\n                    <text x=\"550\" y=\"335\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Trust erodes. Unsubscribes rise.</text>\n                    <rect x=\"100\" y=\"420\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"485\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">JUST RIGHT (6:1)</text>\n                    <text x=\"550\" y=\"535\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Value dominates. Sales feel natural.</text>\n                    <text x=\"550\" y=\"575\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Audience welcomes the occasional ask.</text>\n                    <rect x=\"100\" y=\"660\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(245,158,11,0.1)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"26\">TOO COLD (10:1+)</text>\n                    <text x=\"550\" y=\"775\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Money left on the table</text>\n                    <text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Audience ignores sales when they come</text>\n                </svg>",
