      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">MONETIZATION ROADMAP</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Milestones, not dates</text>\n                    <rect x=\"100\" y=\"170\" width=\"900\" height=\"140\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"220\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">0 - 1K SUBS</text>\n                    <text x=\"170\" y=\"260\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Sell nothing. Pure value.</text>\n                    <text x=\"170\" y=\"292\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Note which topics spark replies — future products</text>\n                    <rect x=\"100\" y=\"330\" width=\"900\" height=\"140\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"380\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">~10K SUBS</text>\n                    <text x=\"170\" y=\"420\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">First high-margin offer: $500-$5K services/cohort</text>\n                    <text x=\"170\" y=\"452\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Survey, interview, pre-sell, then build</text>\n                    <rect x=\"100\" y=\"490\" width=\"900\" height=\"140\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"540\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">~25K SUBS</text>\n                    <text x=\"170\" y=\"580\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Flagship: signature course, event, or book</text>\n                    <text x=\"170\" y=\"612\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">The big moment your audience anticipates</text>\n                    <rect x=\"100\" y=\"650\" width=\"900\" height=\"140\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"700\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">~50K SUBS</text>\n                    <text x=\"170\" y=\"740\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Sponsorship and ads — finally meaningful rates</text>\n                    <text x=\"170\" y=\"772\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Full disclosure, only what you'd recommend</text>\n                    <rect x=\"100\" y=\"810\" width=\"900\" height=\"140\" rx=\"20\" fill=\"rgba(236,72,153,0.15)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"170\" y=\"860\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"24\">~100K SUBS</text>\n                    <text x=\"170\" y=\"900\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Recurring: membership, paid tier, certification</text>\n                    <text x=\"170\" y=\"932\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">Adjust thresholds to your niche — never the order</text>\n                </svg>",
