      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n<rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n<text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"32\">YOUR METRICS AUDIT</text>\n<text x=\"550\" y=\"113\" text-anchor=\"middle\" fill=\"#888\" font-size=\"21\">Five steps before your next check-in</text>\n<rect x=\"140\" y=\"170\" width=\"820\" height=\"110\" rx=\"18\" fill=\"rgba(99,102,241,0.14)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n<text x=\"190\" y=\"225\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">1</text>\n<text x=\"240\" y=\"225\" fill=\"#ffffff\" font-size=\"18\">Name your actual growth stage</text>\n<rect x=\"140\" y=\"300\" width=\"820\" height=\"110\" rx=\"18\" fill=\"rgba(139,92,246,0.14)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n<text x=\"190\" y=\"355\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">2</text>\n<text x=\"240\" y=\"355\" fill=\"#ffffff\" font-size=\"18\">List every metric you currently track</text>\n<rect x=\"140\" y=\"430\" width=\"820\" height=\"110\" rx=\"18\" fill=\"rgba(16,185,129,0.14)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n<text x=\"190\" y=\"485\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">3</text>\n<text x=\"240\" y=\"485\" fill=\"#ffffff\" font-size=\"18\">Mute the metrics from later stages</text>\n<rect x=\"140\" y=\"560\" width=\"820\" height=\"110\" rx=\"18\" fill=\"rgba(245,158,11,0.14)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n<text x=\"190\" y=\"615\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">4</text>\n<text x=\"240\" y=\"615\" fill=\"#ffffff\" font-size=\"18\">Pick this quarter's single scoreboard number</text>\n<rect x=\"140\" y=\"690\" width=\"820\" height=\"110\" rx=\"18\" fill=\"rgba(236,72,153,0.14)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n<text x=\"190\" y=\"745\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">5</text>\n<text x=\"240\" y=\"745\" fill=\"#ffffff\" font-size=\"18\">Set a numeric threshold to graduate rungs</text>\n<rect x=\"140\" y=\"830\" width=\"820\" height=\"100\" rx=\"18\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n<text x=\"550\" y=\"888\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"18\">A threshold turns patience into a plan</text>\n</svg>",
