      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n<rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n<text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"32\">KNOWLEDGE CHECK</text>\n<text x=\"550\" y=\"113\" text-anchor=\"middle\" fill=\"#888\" font-size=\"21\">500,000 followers, zero email list</text>\n<rect x=\"100\" y=\"180\" width=\"900\" height=\"200\" rx=\"18\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n<text x=\"550\" y=\"235\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">RENTED ATTENTION</text>\n<text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"19\">Large reach, but on someone else's terms</text>\n<text x=\"550\" y=\"315\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">One policy change can remove most of it</text>\n<rect x=\"100\" y=\"420\" width=\"430\" height=\"170\" rx=\"18\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n<text x=\"315\" y=\"475\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"20\">2018 EXAMPLE</text>\n<text x=\"315\" y=\"515\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">Facebook Pages lost</text>\n<text x=\"315\" y=\"545\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">half their reach overnight</text>\n<rect x=\"570\" y=\"420\" width=\"430\" height=\"170\" rx=\"18\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n<text x=\"785\" y=\"475\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">THE FIX</text>\n<text x=\"785\" y=\"515\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">Convert followers into</text>\n<text x=\"785\" y=\"545\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">an owned email list</text>\n<rect x=\"100\" y=\"630\" width=\"900\" height=\"100\" rx=\"18\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n<text x=\"550\" y=\"688\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"18\">Reach and ownership are not the same thing</text>\n</svg>",
